#!/usr/bin/env bun
/**
 * generate-page-md — per-page markdown emission (Phase 3 grammar).
 *
 * Every component family (web + mobile) and every foundations page emits its
 * own .md under public/md/, in grammar order, from the same content the
 * pages render. These files are the machine surface for future agent
 * consumers — the committed llms.txt maps the pages, these carry them.
 *
 * BUILD OUTPUT, not committed artefacts: public/md/ is gitignored and
 * regenerated by `bun run generate` (hence into the deployed bundle via
 * public/). Committing 200 generated files would put them under the root
 * generated-artifacts census, whose registry this lane does not own — an
 * unregistered committed artefact is exactly what that gate fails. The
 * freshness contract lives in check-page-md instead: it re-runs this same
 * module per page and asserts every docs page emits a well-formed .md.
 */
import { mkdirSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { FOUNDATIONS, neighbours } from "../src/foundations/shell.tsx";
import { foundationMarkdown, pageMarkdown } from "./lib/page-md.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const APP = join(HERE, "..");
const OUT = join(APP, "public", "md");

async function loadDocs(subdir) {
  const dir = join(APP, "src", "content", subdir);
  const docs = [];
  for (const file of readdirSync(dir)
    .filter((f) => f.endsWith(".ts"))
    .sort()) {
    const mod = await import(join(dir, file));
    for (const doc of Object.values(mod)) {
      if (doc && typeof doc === "object" && doc.slug && doc.name)
        docs.push(doc);
    }
  }
  return docs;
}

const { WEB_DEMOS } = await import(
  join(APP, "src", "demos", "web", "registry.tsx")
);
const { MOBILE_DEMOS } = await import(
  join(APP, "src", "demos", "mobile", "registry.tsx")
);
const registries = { web: WEB_DEMOS, mobile: MOBILE_DEMOS };

let count = 0;
for (const platform of ["web", "mobile"]) {
  const dir = join(OUT, platform);
  mkdirSync(dir, { recursive: true });
  for (const doc of await loadDocs(platform)) {
    const liveDemo = registries[platform][doc.parts[0]] !== undefined;
    const md =
      `<!-- Do not hand-edit: written by scripts/generate-page-md.mjs from src/content/${platform}/${doc.slug}.ts. -->\n` +
      pageMarkdown(doc, platform, { liveDemo });
    writeFileSync(join(dir, `${doc.slug}.md`), md);
    count += 1;
  }
}

{
  const dir = join(OUT, "foundations");
  mkdirSync(dir, { recursive: true });
  for (const page of FOUNDATIONS) {
    const md =
      `<!-- Do not hand-edit: written by scripts/generate-page-md.mjs from the foundations registry. -->\n` +
      foundationMarkdown(page, neighbours(page.slug));
    writeFileSync(join(dir, `${page.slug}.md`), md);
    count += 1;
  }
}

console.log(`generate-page-md: wrote ${count} page(s) to public/md/`);
